Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_reqTrans">ReqTrans</param>
protected void updateInventReference(ReqTrans   _reqTrans)
{
    reqMarkUpdate   locReqMarkUpdate = reqMarkUpdate;
    ReqGroup        reqGroup      = ReqGroup::find(InventTable::find(_reqTrans.ItemId).ReqGroupId);
    ReqParameters   reqParameters = ReqParameters::find();

    if (reqParameters.KCS_OnlyMarkIndividual == NoYes::Yes && reqGroup.CovRule != ReqCovType::Req)
    {
        reqMarkUpdate = reqMarkUpdate::No;
    }

    next updateInventReference(_reqTrans);

    reqMarkUpdate = locReqMarkUpdate;
}
